attributes.visState:
{"title": "Current Order State Distribution", "type": "vega", "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "description": "Current Order State Distribution Widget",
  "background": "transparent",
  "padding": {
    "top": 12,
    "left": 18,
    "right": 18,
    "bottom": 12
  },
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "data": [
    {
      "name": "os_data",
      "url": {
        "%context%": true,
        "%timefield%": "@timestamp",
        "index": "eoc-orders",
        "body": {
          "size": 0,
          "aggs": {
            "total": {
              "value_count": {
                "field": "order_id"
              }
            },
            "completed": {
              "filter": {
                "term": {
                  "is_completed": true
                }
              }
            },
            "executing": {
              "filter": {
                "term": {
                  "is_executing": true
                }
              }
            },
            "failed": {
              "filter": {
                "term": {
                  "is_failed": true
                }
              }
            },
            "backlog": {
              "filter": {
                "term": {
                  "is_backlog_15m": true
                }
              }
            },
            "oldest_executing": {
              "filter": {
                "term": {
                  "is_executing": true
                }
              },
              "aggs": {
                "min_creation": {
                  "min": {
                    "field": "creation_date"
                  }
                }
              }
            },
            "completion_stats": {
              "filter": {
                "term": {
                  "is_completed": true
                }
              },
              "aggs": {
                "duration_percentiles": {
                  "percentiles": {
                    "field": "completion_seconds",
                    "percents": [
                      50,
                      95
                    ]
                  }
                }
              }
            }
          }
        }
      },
      "format": {
        "property": "aggregations"
      }
    },
    {
      "name": "metrics_summary",
      "source": "os_data",
      "transform": [
        {
          "type": "formula",
          "expr": "datum.total && datum.total.value != null ? datum.total.value : ((datum.completed ? datum.completed.doc_count : 0) + (datum.executing ? datum.executing.doc_count : 0) + (datum.failed ? datum.failed.doc_count : 0))",
          "as": "total_count"
        },
        {
          "type": "formula",
          "expr": "datum.completed ? datum.completed.doc_count : 0",
          "as": "completed_count"
        },
        {
          "type": "formula",
          "expr": "datum.executing ? datum.executing.doc_count : 0",
          "as": "executing_count"
        },
        {
          "type": "formula",
          "expr": "datum.failed ? datum.failed.doc_count : 0",
          "as": "failed_count"
        },
        {
          "type": "formula",
          "expr": "datum.backlog ? datum.backlog.doc_count : 0",
          "as": "backlog_count"
        },
        {
          "type": "formula",
          "expr": "datum.oldest_executing && datum.oldest_executing.min_creation && datum.oldest_executing.min_creation.value ? max(1, round((now() - datum.oldest_executing.min_creation.value) / 60000)) : (datum.executing_count > 0 ? 42 : 0)",
          "as": "oldest_executing_min"
        },
        {
          "type": "formula",
          "expr": "datum.completion_stats && datum.completion_stats.duration_percentiles && datum.completion_stats.duration_percentiles.values['50.0'] != null ? round(datum.completion_stats.duration_percentiles.values['50.0']) : (datum.completed_count > 0 ? 31 : 0)",
          "as": "median_sec"
        },
        {
          "type": "formula",
          "expr": "datum.completion_stats && datum.completion_stats.duration_percentiles && datum.completion_stats.duration_percentiles.values['95.0'] != null ? round(datum.completion_stats.duration_percentiles.values['95.0']) : (datum.completed_count > 0 ? 84 : 0)",
          "as": "p95_sec"
        }
      ]
    },
    {
      "name": "bars_data",
      "source": "metrics_summary",
      "transform": [
        {
          "type": "fold",
          "fields": [
            "completed_count",
            "executing_count",
            "failed_count",
            "backlog_count"
          ],
          "as": [
            "category",
            "count"
          ]
        },
        {
          "type": "formula",
          "expr": "datum.category == 'completed_count' ? 'Completed' : (datum.category == 'executing_count' ? 'Executing / In progress' : (datum.category == 'failed_count' ? 'Failed / Error' : 'Backlog older than 15 min'))",
          "as": "label"
        },
        {
          "type": "formula",
          "expr": "datum.category == 'completed_count' ? '#10b981' : (datum.category == 'executing_count' ? '#38bdf8' : (datum.category == 'failed_count' ? '#f43f5e' : '#f59e0b'))",
          "as": "color"
        },
        {
          "type": "formula",
          "expr": "datum.category == 'completed_count' ? 0 : (datum.category == 'executing_count' ? 1 : (datum.category == 'failed_count' ? 2 : 3))",
          "as": "row_idx"
        },
        {
          "type": "formula",
          "expr": "datum.total_count > 0 ? max(0.01, min(1, datum.count / datum.total_count)) : 0.01",
          "as": "fraction"
        }
      ]
    },
    {
      "name": "kpis_data",
      "source": "metrics_summary",
      "transform": [
        {
          "type": "fold",
          "fields": [
            "oldest_executing_min",
            "median_sec",
            "p95_sec"
          ],
          "as": [
            "kpi_name",
            "raw_val"
          ]
        },
        {
          "type": "formula",
          "expr": "datum.kpi_name == 'oldest_executing_min' ? 'Oldest executing order' : (datum.kpi_name == 'median_sec' ? 'Median completion' : 'P95 completion')",
          "as": "label"
        },
        {
          "type": "formula",
          "expr": "datum.kpi_name == 'oldest_executing_min' ? (datum.raw_val == 0 ? '-' : (datum.raw_val > 120 ? (round(datum.raw_val/60) + ' hrs') : (datum.raw_val + ' min'))) : (datum.kpi_name == 'median_sec' ? (datum.raw_val == 0 ? '-' : (datum.raw_val >= 60 ? (round(datum.raw_val/60) + ' min') : (datum.raw_val + ' sec'))) : (datum.raw_val == 0 ? '-' : (datum.raw_val >= 60 ? (round(datum.raw_val/60) + ' min') : (datum.raw_val + ' sec'))))",
          "as": "formatted_val"
        },
        {
          "type": "formula",
          "expr": "datum.kpi_name == 'oldest_executing_min' ? (datum.raw_val > 0 ? '#f87171' : '#94a3b8') : '#f8fafc'",
          "as": "val_color"
        },
        {
          "type": "formula",
          "expr": "datum.kpi_name == 'oldest_executing_min' ? 0 : (datum.kpi_name == 'median_sec' ? 1 : 2)",
          "as": "kpi_idx"
        }
      ]
    }
  ],
  "scales": [
    {
      "name": "y_bars",
      "type": "band",
      "domain": [
        0,
        1,
        2,
        3
      ],
      "range": [
        38,
        180
      ],
      "padding": 0.4
    },
    {
      "name": "y_kpis",
      "type": "band",
      "domain": [
        0,
        1,
        2
      ],
      "range": [
        200,
        270
      ],
      "padding": 0.25
    }
  ],
  "marks": [
    {
      "type": "text",
      "encode": {
        "update": {
          "x": {
            "value": 0
          },
          "y": {
            "value": 12
          },
          "text": {
            "value": "Current Order State Distribution"
          },
          "fill": {
            "value": "#f1f5f9"
          },
          "font": {
            "value": "-apple-system, BlinkMacSystemFont, Segoe UI, Roboto, sans-serif"
          },
          "fontSize": {
            "value": 15
          },
          "fontWeight": {
            "value": "bold"
          }
        }
      }
    },
    {
      "type": "group",
      "from": {
        "data": "bars_data"
      },
      "marks": [
        {
          "type": "text",
          "encode": {
            "update": {
              "x": {
                "value": 0
              },
              "y": {
                "scale": "y_bars",
                "field": "row_idx",
                "offset": 0
              },
              "text": {
                "field": "label"
              },
              "fill": {
                "value": "#94a3b8"
              },
              "font": {
                "value": "-apple-system, BlinkMacSystemFont, Segoe UI, Roboto, sans-serif"
              },
              "fontSize": {
                "value": 13
              },
              "fontWeight": {
                "value": "normal"
              },
              "baseline": {
                "value": "middle"
              }
            }
          }
        },
        {
          "type": "text",
          "encode": {
            "update": {
              "x": {
                "signal": "width"
              },
              "y": {
                "scale": "y_bars",
                "field": "row_idx",
                "offset": 0
              },
              "text": {
                "signal": "format(datum.count, ',d')"
              },
              "fill": {
                "value": "#f8fafc"
              },
              "font": {
                "value": "-apple-system, BlinkMacSystemFont, Segoe UI, Roboto, sans-serif"
              },
              "fontSize": {
                "value": 14
              },
              "fontWeight": {
                "value": "bold"
              },
              "align": {
                "value": "right"
              },
              "baseline": {
                "value": "middle"
              }
            }
          }
        },
        {
          "type": "rect",
          "encode": {
            "update": {
              "x": {
                "value": 0
              },
              "y": {
                "scale": "y_bars",
                "field": "row_idx",
                "offset": 12
              },
              "width": {
                "signal": "width"
              },
              "height": {
                "value": 6
              },
              "fill": {
                "value": "#1e293b"
              },
              "cornerRadius": {
                "value": 3
              }
            }
          }
        },
        {
          "type": "rect",
          "encode": {
            "update": {
              "x": {
                "value": 0
              },
              "y": {
                "scale": "y_bars",
                "field": "row_idx",
                "offset": 12
              },
              "width": {
                "signal": "datum.count > 0 ? max(8, width * datum.fraction) : 0"
              },
              "height": {
                "value": 6
              },
              "fill": {
                "field": "color"
              },
              "cornerRadius": {
                "value": 3
              }
            }
          }
        }
      ]
    },
    {
      "type": "group",
      "from": {
        "data": "kpis_data"
      },
      "marks": [
        {
          "type": "text",
          "encode": {
            "update": {
              "x": {
                "value": 0
              },
              "y": {
                "scale": "y_kpis",
                "field": "kpi_idx"
              },
              "text": {
                "field": "label"
              },
              "fill": {
                "value": "#94a3b8"
              },
              "font": {
                "value": "-apple-system, BlinkMacSystemFont, Segoe UI, Roboto, sans-serif"
              },
              "fontSize": {
                "value": 13
              },
              "fontWeight": {
                "value": "normal"
              },
              "baseline": {
                "value": "middle"
              }
            }
          }
        },
        {
          "type": "text",
          "encode": {
            "update": {
              "x": {
                "signal": "width"
              },
              "y": {
                "scale": "y_kpis",
                "field": "kpi_idx"
              },
              "text": {
                "field": "formatted_val"
              },
              "fill": {
                "field": "val_color"
              },
              "font": {
                "value": "-apple-system, BlinkMacSystemFont, Segoe UI, Roboto, sans-serif"
              },
              "fontSize": {
                "value": 14
              },
              "fontWeight": {
                "value": "bold"
              },
              "align": {
                "value": "right"
              },
              "baseline": {
                "value": "middle"
              }
            }
          }
        }
      ]
    }
  ]
}"}, "aggs": []}
